     private static ReadOnlySpan<byte> NibbleLut => [
         0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
         0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
     ];

     public static void ReverseInPlace(Span<byte> data)
     {
         if (Vector256.IsHardwareAccelerated)
         {
             ReverseVector256(data);
         }
         else if (Vector128.IsHardwareAccelerated)
         {
             ReverseVector128(data);
         }
         else
         {
             ReverseScalar(data);
         }
     }

     [MethodImpl(MethodImplOptions.AggressiveInlining)]
     private static void ReverseVector256(Span<byte> data)
     {
         Vector256<byte> lut = Vector256.Create(
             Vector128.Create(NibbleLut),
             Vector128.Create(NibbleLut));
         Vector256<byte> mask = Vector256.Create((byte)0x0F);

         ref byte ptr = ref MemoryMarshal.GetReference(data);
         int i = 0;
         int lastBlockStart = data.Length - Vector256<byte>.Count;

         while (i <= lastBlockStart)
         {
             Vector256<byte> vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);

             // Reverse bits by looking up each nibble and swapping hi/lo nibble positions
             Vector256<byte> lo = vec & mask;
             Vector256<byte> hi = Vector256.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & mask;

             Vector256<byte> reversedLo = Vector256.Shuffle(lut, lo);
             Vector256<byte> reversedHi = Vector256.Shuffle(lut, hi);

             // reversed lo nibble becomes hi nibble, reversed hi nibble becomes lo nibble
             Vector256<byte> result = Vector256.ShiftLeft(reversedLo.AsInt16(), 4).AsByte() | reversedHi;

             result.StoreUnsafe(ref ptr, (nuint)i);
             i += Vector256<byte>.Count;
         }

         // Handle remaining bytes
         for (; i < data.Length; i++)
         {
             data[i] = ReverseByte(data[i]);
         }
     }

     [MethodImpl(MethodImplOptions.AggressiveInlining)]
     private static void ReverseVector128(Span<byte> data)
     {
         Vector128<byte> lut = Vector128.Create(NibbleLut);
         Vector128<byte> mask = Vector128.Create((byte)0x0F);

         ref byte ptr = ref MemoryMarshal.GetReference(data);
         int i = 0;
         int lastBlockStart = data.Length - Vector128<byte>.Count;

         while (i <= lastBlockStart)
         {
             Vector128<byte> vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);

             Vector128<byte> lo = vec & mask;
             Vector128<byte> hi = Vector128.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & mask;

             Vector128<byte> reversedLo = Vector128.Shuffle(lut, lo);
             Vector128<byte> reversedHi = Vector128.Shuffle(lut, hi);

             Vector128<byte> result = Vector128.ShiftLeft(reversedLo.AsInt16(), 4).AsByte() | reversedHi;

             result.StoreUnsafe(ref ptr, (nuint)i);
             i += Vector128<byte>.Count;
         }

         for (; i < data.Length; i++)
         {
             data[i] = ReverseByte(data[i]);
         }
     }

